sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api}) {

  const user = api.context.session.user;

  // Stop if session not ready
  if (!user || !user.roles) {
    return;
  }

  const roles = user.roles;

  // Alumni redirect
  if (roles.includes('alumni')) {
    api.navigation.openUrl('/x/1909965/alumni-portal/dashboard');
    return;
  }

  // Student redirect
  if (roles.includes('student')) {
    api.navigation.openUrl('/x/1909965/almaconnect/student-dashboard');
    return;
  }

}
